#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Keep the tracker reachable by Unreal's garbage collector for the match.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker was a raw UObject pointer without UPROPERTY. NewObject's Outer (the game mode) does not by itself keep the tracker reachable by garbage collection. The packaged log records GC at 21:05:13 followed by an access violation in UArenaScoreTracker::AddPoints on the next recorded goal at 21:05:27, consistent with use of a collected tracker. Fixed by storing it in a UPROPERTY TObjectPtr so the live game mode keeps it reachable.",
  "no_colors_cause": "The palette is loaded only through a literal LoadObject path, which does not establish a cooker-discoverable asset reference. With bCookAll=False and no always-cook entry for /Game/Data/Palettes, the palette was omitted from the packaged build. The log explicitly reports the missing /Game/Data/Palettes/DA_Primary package and fallback gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook.",
  "assumptions": [
    "The palette asset exists in the full project at /Game/Data/Palettes/DA_Primary.DA_Primary, as implied by correct editor behavior; asset files are not supplied here.",
    "FArenaStats is plain C++ data as documented in the header; its existing new/delete lifetime is intentional and is not subject to Unreal garbage collection."
  ],
  "validation": "Static inspection confirms all three persistent UObject members are now UPROPERTY TObjectPtr references, the palette's directory is explicitly cooked, and the /Game/Dev exclusion does not overlap it. No Unreal Engine is installed, so compilation, cooking, and runtime validation were not performed. On an engine-equipped machine, package again, verify palette loading and colors, then trigger garbage collection and score goals to confirm the tracker survives."
}
